#!/bin/bash
D=/home/jhan/workspace/intel-AMX/exec/3b35-inspect-20261112
H=$(hostname -s)
o() { local n=$1; shift; { echo "# host=$H date=$(date -u +%FT%TZ)"; echo "# cmd: $*"; timeout 60 bash -c "$*" 2>&1; } > "$D/io-irq-background-$H-$n.txt"; }
o thermal2 'for c in 0 72; do d=/sys/devices/system/cpu/cpu$c/thermal_throttle; echo "cpu$c (package $(cat /sys/devices/system/cpu/cpu$c/topology/physical_package_id)): $(for f in $d/*; do echo -n "$(basename $f)=$(cat $f) "; done)"; done; echo "per-package: sum of core_throttle_count over cpus, and distinct package_throttle_count values:"; for p in 0 1; do s=0; vals=""; for d in /sys/devices/system/cpu/cpu[0-9]*; do [ "$(cat $d/topology/physical_package_id)" = "$p" ] || continue; s=$((s+$(cat $d/thermal_throttle/core_throttle_count))); vals="$vals $(cat $d/thermal_throttle/package_throttle_count)"; done; echo "package $p core_sum=$s pkg_count_min_max=$(echo $vals | tr " " "\n" | sort -n | sed -n "1p;\$p" | tr "\n" " ")"; done; for z in /sys/class/thermal/thermal_zone*; do echo "$(basename $z) $(cat $z/type) temp=$(cat $z/temp 2>/dev/null)"; done; for h in /sys/class/hwmon/hwmon*; do n=$(cat $h/name 2>/dev/null); [ "$n" = coretemp ] && echo "$h $n $(cat $h/temp1_label) input=$(cat $h/temp1_input) max=$(cat $h/temp1_max 2>/dev/null) crit=$(cat $h/temp1_crit 2>/dev/null)"; done; uptime'
o rinzler 'for p in $(pgrep -x rinzler); do echo "pid $p user=$(ps -o user= -p $p) etimes=$(ps -o etimes= -p $p)s pcpu=$(ps -o pcpu= -p $p)"; tr "\0" " " < /proc/$p/cmdline | cut -c1-900; echo; grep -E "Cpus_allowed_list|Mems_allowed_list|Threads" /proc/$p/status; echo "threads with pcpu>=5, by socket (node0 = cpu 0-71,144-215):"; ps -L -o psr=,pcpu=,comm= -p $p | awk "\$2>=5{n=(\$1<72||(\$1>=144&&\$1<216))?0:1; c[n]++; s[n]+=\$2} END{for(k in c) print \"socket\" k, c[k] \" threads\", s[k] \" %cpu\"}"; echo "busy thread cpus:"; ps -L -o psr=,pcpu= -p $p | awk "\$2>=5{printf \"%s \", \$1}"; echo; done; echo; echo "who:"; who | awk "{print \$1}" | sort | uniq -c; echo; echo "non-kernel processes >=1 %cpu:"; ps -eo user,psr,pcpu,nlwp,etimes,comm --sort=-pcpu | awk "NR==1||\$3>=1.0"'
o misc 'echo "irqbalance config:"; grep -v "^#" /etc/default/irqbalance 2>&1 | grep -v "^$"; echo "(end)"; echo; echo "dockerd/containerd pids: $(pgrep -x "dockerd|containerd|podman|libvirtd|qemu-system-x86" | tr "\n" " ")(end)"; echo; echo "timers:"; systemctl list-timers --no-pager --all 2>&1 | awk "{print \$NF, \$(NF-1)}" | sort | head -30; echo; echo "xhci irq cpu:"; grep xhci /proc/interrupts | awk "{for(i=2;i<=289;i++) if(\$i>1000000) printf \"cpu%d=%s \", i-2, \$i; print \"\"}"; for i in $(grep xhci /proc/interrupts | awk -F: "{print \$1}"); do echo "irq $i affinity_list=$(cat /proc/irq/$i/smp_affinity_list) effective=$(cat /proc/irq/$i/effective_affinity_list)"; done; echo; echo "rtm/hle flags: $(grep -m1 "^flags" /proc/cpuinfo | tr " " "\n" | grep -cx rtm) $(grep -m1 "^flags" /proc/cpuinfo | tr " " "\n" | grep -cx hle)"; echo "tsx_async_abort: $(cat /sys/devices/system/cpu/vulnerabilities/tsx_async_abort)"; echo; echo "fpga [8200:0011] devices:"; lspci -nn -d 8200:0011 | cut -c1-60; echo "numa of each:"; for d in $(lspci -D -d 8200:0011 | awk "{print \$1}"); do echo "$d numa=$(cat /sys/bus/pci/devices/$d/numa_node) driver=$(basename $(readlink /sys/bus/pci/devices/$d/driver 2>/dev/null) 2>/dev/null)"; done; echo; echo "nvme numa:"; for n in /sys/class/nvme/nvme*; do echo "$(basename $n) $(cat $n/address) numa=$(cat $n/device/numa_node) model=$(cat $n/model)"; done; echo; echo "sudo -n: $(sudo -n true 2>&1 && echo works)"'
echo done $H
